def seed(apps, schema_editor):
    """Existing installs get the new country searches and company boards once (like migration 0033 did for the Gulf). Only entries
    that are missing are added, and only when the install already uses the default sources (an admin who runs their own list is
    left alone). Fresh installs got everything from migration 0031. Not in tests."""
    if not settings.STILLOPEN_SEED_SOURCES:
        return
    JobSource = apps.get_model("tracker", "JobSource")
    if not JobSource.objects.filter(owner__isnull=True).exists():
        return
    for name, connector, token in REGIONAL_MORE + JOOBLE_MORE + ADZUNA + OPEN_SEARCH:
        JobSource.objects.get_or_create(owner=None, connector=connector, board_token=token, defaults={"name": name, "enabled": True})


